-- F03 (client-spec audit), second step: the server also enforces each workbook form's conditional
-- rules, the required columns of filled rows, the "Other" explanations and number bounds.
--
-- app_private.spec_form_rules() is regenerated from apps/web/lib/forms/spec-forms.ts
-- (scripts/generate-spec-server-rules.mjs, written here by scripts/write-spec-rules-migration.mjs;
-- tests/spec-server-rules.test.mjs keeps them equal). The form's visible/required conditions are
-- SpecCondition objects, so the form and app_private.spec_rule_holds evaluate the same rule.
--
-- When they apply (unchanged from 202611230004):
-- * every save by a signed-in user: a changed fixed-list value must be on its list, a changed number
--   must be within its bounds;
-- * a save from the current form (spec carries "_rules") and every formal submission/resubmission:
--   also the always-required and conditionally required fields, required row columns and the
--   explanation of an "Other" choice.
-- Older offline payloads without the marker are not stopped in the queue; their formal submission is.
-- Sensitive incident fields are moved to the restricted table before this check and stay a form rule.
-- Nothing here rewrites stored data.

create or replace function app_private.spec_form_rules()
returns jsonb
language sql
immutable
set search_path = pg_catalog
