-- Does a SpecCondition hold for a spec object? Mirrors specConditionHolds in spec-forms.ts.
create or replace function app_private.spec_rule_holds(p_rule jsonb, p_spec jsonb)
returns boolean
language plpgsql
immutable
set search_path = pg_catalog, app_private
as $$
declare
  v_values text[];
  v_a text;
  v_b text;
  v_item jsonb;
begin
  if p_rule ? 'not' then return not app_private.spec_rule_holds(p_rule -> 'not', p_spec); end if;
  if p_rule ? 'all' then
    for v_item in select value from jsonb_array_elements(p_rule -> 'all') loop
      if not app_private.spec_rule_holds(v_item, p_spec) then return false; end if;
    end loop;
    return true;
  end if;
  if p_rule ? 'any' then
    for v_item in select value from jsonb_array_elements(p_rule -> 'any') loop
      if app_private.spec_rule_holds(v_item, p_spec) then return true; end if;
    end loop;
    return false;
  end if;
  if p_rule ? 'differ' or p_rule ? 'earlier' then
    v_a := nullif(btrim(p_spec ->> (coalesce(p_rule -> 'differ', p_rule -> 'earlier') ->> 0)), '');
    v_b := nullif(btrim(p_spec ->> (coalesce(p_rule -> 'differ', p_rule -> 'earlier') ->> 1)), '');
    if v_a is null or v_b is null then return false; end if;
    if p_rule ? 'earlier' then return v_a < v_b; end if;
    begin
      return v_a::numeric <> v_b::numeric;
    exception when others then
      return v_a <> v_b;
    end;
  end if;
  v_values := app_private.spec_values(p_spec -> (p_rule ->> 'key'));
  if p_rule ? 'filled' then return cardinality(v_values) > 0; end if;
  if p_rule ? 'in' then
    return exists (select 1 from unnest(v_values) item where (p_rule -> 'in') ? item);
  end if;
  if p_rule ? 'match' then
    return exists (select 1 from unnest(v_values) item where item ~* (p_rule ->> 'match'));
  end if;
  return false;
end;
$$;

create or replace function app_private.spec_violations(p_form text, p_spec jsonb, p_old jsonb, p_check_required boolean)
returns text[]
language plpgsql
stable
set search_path = pg_catalog, app_private
as $$
declare
  v_rules jsonb := app_private.spec_form_rules() -> p_form;
  v_out text[] := '{}';
  v_key text;
  v_allowed jsonb;
  v_value text;
  v_group text;
  v_label text;
  v_rule jsonb;
  v_row jsonb;
  v_column text;
  v_index integer;
  v_number numeric;
  v_empty boolean;
begin
  if v_rules is null or jsonb_typeof(p_spec) <> 'object' then return v_out; end if;
  if p_check_required then
    for v_key in select jsonb_array_elements_text(v_rules -> 'required') loop
      if cardinality(app_private.spec_values(p_spec -> v_key)) = 0 then
        v_out := v_out || ('Required: ' || coalesce(v_rules #>> array['labels', v_key], v_key));
      end if;
    end loop;
    for v_key in select jsonb_array_elements_text(v_rules -> 'rows') loop
      if jsonb_typeof(p_spec -> v_key) is distinct from 'array' or jsonb_array_length(p_spec -> v_key) = 0 then
        v_out := v_out || ('Required: ' || coalesce(v_rules #>> array['labels', v_key], v_key));
      end if;
    end loop;
    -- Required when the form's condition holds (e.g. a closure note once Closed).
    for v_rule in select value from jsonb_array_elements(coalesce(v_rules -> 'conditional', '[]'::jsonb)) loop
      v_key := v_rule ->> 'key';
      continue when not app_private.spec_rule_holds(v_rule -> 'when', p_spec);
      v_empty := case when coalesce((v_rule ->> 'rows')::boolean, false)
          then jsonb_typeof(p_spec -> v_key) is distinct from 'array' or jsonb_array_length(p_spec -> v_key) = 0
          else cardinality(app_private.spec_values(p_spec -> v_key)) = 0 end;
      if v_empty then
        v_out := v_out || ('Required: ' || coalesce(v_rules #>> array['labels', v_key], v_key));
      end if;
    end loop;
    -- Every stored row has its required columns.
    for v_key, v_allowed in select key, value from jsonb_each(coalesce(v_rules -> 'columns', '{}'::jsonb)) loop
      continue when jsonb_typeof(p_spec -> v_key) is distinct from 'array';
      v_index := 0;
      for v_row in select value from jsonb_array_elements(p_spec -> v_key) loop
        v_index := v_index + 1;
        continue when jsonb_typeof(v_row) <> 'object';
        for v_column in select jsonb_array_elements_text(v_allowed) loop
          if btrim(coalesce(v_row ->> v_column, '')) = '' then
            v_out := v_out || ('Required: ' || coalesce(v_rules #>> array['labels', v_key], v_key) || ' '
              || coalesce(v_row ->> 'step', v_index::text) || ' · ' || coalesce(v_rules #>> array['labels', v_key || '.' || v_column], v_column));
          end if;
        end loop;
      end loop;
    end loop;
    -- Choosing "Other" needs its short explanation.
    for v_key in select jsonb_array_elements_text(coalesce(v_rules -> 'other', '[]'::jsonb)) loop
      if exists (select 1 from unnest(app_private.spec_values(p_spec -> v_key)) item where item ~* '^other\M')
          and cardinality(app_private.spec_values(p_spec -> (v_key || '_other'))) = 0 then
        v_out := v_out || ('Required: ' || coalesce(v_rules #>> array['labels', v_key], v_key) || ' · explanation for Other');
      end if;
    end loop;
  end if;
  -- Numbers within their bounds (changed values only, as for the lists).
  for v_key, v_allowed in select key, value from jsonb_each(coalesce(v_rules -> 'numbers', '{}'::jsonb)) loop
    continue when not p_spec ? v_key;
    continue when p_old is not null and (p_spec -> v_key) is not distinct from (p_old -> v_key);
    foreach v_value in array app_private.spec_values(p_spec -> v_key) loop
      v_label := coalesce(v_rules #>> array['labels', v_key], v_key);
      begin
        v_number := v_value::numeric;
      exception when others then
        v_out := v_out || (v_label || ': "' || v_value || '" is not a number');
        continue;
      end;
      if (v_allowed ->> 'min' is not null and v_number < (v_allowed ->> 'min')::numeric)
          or (v_allowed ->> 'max' is not null and v_number > (v_allowed ->> 'max')::numeric) then
        v_out := v_out || (v_label || ': ' || v_value || ' is out of range');
      end if;
    end loop;
  end loop;
  for v_key, v_allowed in select key, value from jsonb_each(coalesce(v_rules -> 'options', '{}'::jsonb)) loop
    continue when not p_spec ? v_key;
    continue when p_old is not null and (p_spec -> v_key) is not distinct from (p_old -> v_key);
    foreach v_value in array app_private.spec_values(p_spec -> v_key) loop
      if not v_allowed ? v_value then
        v_out := v_out || (coalesce(v_rules #>> array['labels', v_key], v_key) || ': "' || v_value || '" is not one of the list''s values');
      end if;
    end loop;
  end loop;
  for v_key, v_allowed in select key, value from jsonb_each(coalesce(v_rules -> 'dependent', '{}'::jsonb)) loop
    continue when not p_spec ? v_key;
    continue when p_old is not null and (p_spec -> v_key) is not distinct from (p_old -> v_key)
      and (v_allowed ->> 'parent' is null or (p_spec -> (v_allowed ->> 'parent')) is not distinct from (p_old -> (v_allowed ->> 'parent')));
    v_group := case when v_allowed ->> 'parent' is null then 'all' else p_spec ->> (v_allowed ->> 'parent') end;
    continue when v_group is null or not (v_allowed -> 'groups') ? v_group;
    v_label := coalesce(v_rules #>> array['labels', v_key], v_key);
    foreach v_value in array app_private.spec_values(p_spec -> v_key) loop
      if not (v_allowed #> array['groups', v_group]) ? v_value then
        v_out := v_out || (v_label || ': "' || v_value || '" does not belong to "' || v_group || '"');
      end if;
    end loop;
  end loop;
  return v_out;
end;
$$;
